entries[3124] = { ["name"] = "Codex of Inner Fire III", ["text"] = "Classes: Priest\nRequires Level 30\nUse: Teaches Inner Fire (Rank 3).\n\nA burst of Holy energy fills the caster, increasing armor by 945. Each melee or ranged damage hit against the priest will remove one charge. Lasts 10 min or until 20 charges are used.\nSell Price:" }
entries[3125] = { ["name"] = "Tablet of Serpent Totem II", ["text"] = "Classes: Shaman\nRequires Level 10\nUse: Teaches Serpent Totem (Rank 2).\n\nSummons a Searing Totem with 5 health at your feet for 35 sec that repeatedly attacks an enemy within 20 yards for 13 to 17 Fire damage.\nSell Price:" }
entries[3126] = { ["name"] = "Tablet of Shock II", ["text"] = "Classes: Shaman\nRequires Level 12\nUse: Teaches Shock (Rank 2).\n\nInstantly throws a bolt of lightning at the target for 61 to 65 damage.\nSell Price:" }
entries[3127] = { ["name"] = "Tablet of Shock III", ["text"] = "Classes: Shaman\nRequires Level 20\nUse: Teaches Shock (Rank 3).\n\nInstantly throws a bolt of lightning at the target for 114 to 122 damage.\nSell Price:" }
entries[3129] = { ["name"] = "Tablet of Lightning Bolt IV", ["text"] = "Classes: Shaman\nRequires Level 26\nUse: Teaches Lightning Bolt (Rank 4).\n\nCasts a bolt of lightning at the target for 88 to 100 Nature damage.\nSell Price:" }
entries[3130] = { ["name"] = "Tablet of Restoration IV", ["text"] = "Classes: Shaman\nRequires Level 24\nUse: Teaches Healing Wave (Rank 4).\n\nHeals a friendly target for 279 to 328.\nSell Price:" }
