entries[3139] = { ["name"] = "Grimoire of Demon Armor II", ["text"] = "Classes: Warlock\nRequires Level 34\nUse: Teaches Demon Armor (Rank 2).\n\nProtects the caster, increasing armor by 300, Shadow resistance by 6 and restores 9 health every 5 sec. Only one type of Armor spell can be active on the Warlock at any time. Lasts 30 min.\nSell Price:" }
